<?php echo form_open(get_uri('suppliers/save'), ['id' => 'supplier-form', 'class' => 'general-form']); ?>
<div class="modal-body"><?php echo view('suppliers/form_fields', ['model_info' => $model_info, 'prefix' => 'supplier']); ?></div>
<div class="modal-footer"><button type="button" class="btn btn-default" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary" type="submit"><i data-feather="check-circle" class="icon-16"></i> Guardar</button></div>
<?php echo form_close(); ?>
<script>$(function(){var form=$('#supplier-form'),existing=null;form.appForm({onSuccess:function(r){$(document).trigger('supplier:created',[r]);},onError:function(r){if(!r.duplicate_supplier){return;}existing=r.existing;var box=form.find('[data-supplier-duplicate]').removeClass('hide');box.find('[data-supplier-duplicate-message]').text(r.message);box.find('[data-supplier-existing-name]').text(existing.name);box.find('[data-supplier-existing-detail]').text([existing.rfc,existing.phone,existing.email].filter(Boolean).join(' · '));box.find('[data-supplier-create-anyway]').toggleClass('hide',!r.allow_create);}});form.on('click','[data-supplier-use-existing]',function(){if(existing){window.location.href='<?php echo get_uri('suppliers/view'); ?>/'+existing.id;}});form.on('click','[data-supplier-create-anyway]',function(){form.find('[data-supplier-allow-similar]').val('1');form.submit();});});</script>
